peppers_per_very_spicy_curry = 5
peppers_per_spicy_curry = 3
peppers_per_mild_curry = 1

# Define the number of each type of curry ordered
num_very_spicy_curries = 20
num_spicy_curries = 20
num_mild_curries = 30

# Calculate the total number of peppers bought without safety stock
