#include <iostream>
#include <cmath>

class PolynomialRegression {
private:
    // x values of the points
    std::vector<double> x;
    // f(x) values corresponding to the x values
    std::vector<double> f;

public:
    PolynomialRegression(const std::vector<double>& x_values, const std::vector<double>& f_values) {
        x = x_values;
        f = f_values;
    }

    double predict(double target_x) {
        // Set up the matrix A and vector b
        std::vector<std::vector<double>> A = {{4, 7, 8}, {3, 5, 5}, {10, 16, 22}};
        std::vector<double> b;

        // Calculate the coefficients c1, c2, c3
        for (int i = 0; i < 3; ++i) {
            double y_of_x_i = std::log(x[i]);
            b.resize(3);
            b[0] = y_of_x_i;
            b[1] = y_of_x_i * x[i];
            b[2] = y_of_x_i * x[i] * x[i];
        }

        // Solve the system of linear equations
        std::vector<double> coefficients = solveLinearSystem(A, b);
        double c1 = coefficients[0];
        double c2 = coefficients[1];
        double c3 = coefficients[2];

        // Calculate the corresponding point at x = target_x
        double f_target_x = std::log(target_x);
        double predictions = c1 * f_target_x + c2 * f_target_x * target_x + c3 * f_target_x * target_x * target_x;
        return predictions;
    }

private:
    std::vector<double> solveLinearSystem(std::vector<std::vector<double>> A, std::vector<double> b) {
        // RREF the augmented matrix [A | b]
        std::vector<std::vector<double>> augmentedMatrix;
        for (int i = 0; i < 3; ++i) {
            std::vector<double> row;
            int k = 0;
            while (k < 3) {
                row.push_back(A[i][k]);
                k++;
            }
            row.push_back(b[i]);
            augmentedMatrix.push_back(row);
        }

        // Perform row reduction
        int rows = augmentedMatrix.size();
        int cols = augmentedMatrix[0].size();
        for (int i = 0; i < rows; ++i) {
            // Find the row with the largest absolute value in the current column
            int pivotRow = i;
            for (int j = i + 1; j < rows; ++j) {
                if (abs(augmentedMatrix[j][i]) > abs(augmentedMatrix[pivotRow][i])) {
                    pivotRow = j;
                }
            }
            // Swap the rows if necessary
            if (pivotRow != i) {
                std::swap(augmentedMatrix[i], augmentedMatrix[pivotRow]);
            }
            // Eliminate the variable for each row below the current one
            for (int j = i + 1; j < rows; ++j) {
                double factor = augmentedMatrix[j][i] / augmentedMatrix[i][i];
                for (int k = i; k < cols; ++k) {
                    augmentedMatrix[j][k] -= factor * augmentedMatrix[i][k];
                }
            }
        }
        // Back-substitute to find the solution
        std::vector<double> solution;
        for (int i = rows - 1; i >= 0; --i) {
            solution.push_back(0);
            for (int j = i - 1; j >= 0; --j) {
                augmentedMatrix[i][cols - 1] -= solution[j] * augmentedMatrix[i][j];
            }
            solution[i] = augmentedMatrix[i][cols - 1] / augmentedMatrix[i][i];
        }
        return solution;
    }
};

int main() {
    // Create the polynomial regression model with log-transformed points
    PolynomialRegression logModel({1, 2, 3, 4}, {0, std::log(2), std::log(3), std::log(4)});

    // Given that target_x is 5, find the corresponding point
    double target_x = 5;
    double predicted_f = logModel.predict(target_x);

    // Print the predicted F target X
    std::cout << "Predicted f(" << target_x << ") = " << predicted_f << std::endl;

    return 0;
}
